#!/bin/sh\n# quote.sh - prints a whimsical post‑apocalyptic quote\n\nquotes=(\n\"Even the sun takes a day off in the wasteland.\"\n\"The last Wi‑Fi signal was a whisper of hope.\"\n\"Radiation? Just nature's way of adding flavor.\"\n\"Remember: every bug is a feature in disguise.\"\n\"Keep calm and reboot the world.\"\n)\n\n# Default index\nindex=${QUOTE_INDEX:-0}\n# Ensure index is within bounds\nif [ "$index" -ge "${#quotes[@]}" ] || [ "$index" -lt 0 ]; then\n  index=0\nfi\n\necho "${quotes[$index]}"\n
